#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, k;
    cin >> n >> m >> k;

    if (k > n + m - 2) {
        cout << -1 << '\n';
        return 0;
    }

    if (n > m) swap(n, m);

    long long answer = 0;

    auto evaluate = [&](long long a) {
        if (a < 1 || a > n) return;

        long long cutsN = a - 1;
        long long cutsM = k - cutsN;

        if (cutsM < 0 || cutsM >= m) return;

        answer = max(answer, (n / a) * (m / (cutsM + 1)));
    };

    for (long long t = 1; t <= n / t; ++t) {
        evaluate(t);
        evaluate(n / t);
    }

    long long upper = min(n, k + 1);
    evaluate(upper);

    cout << answer << '\n';
    return 0;
}

