        cout << -1 << '\n';
        return 0;
    }

    if (n > m) swap(n, m);

    long long left = max(1LL, k - m + 2);
    long long right = min(n, k + 1);
    __int128 answer = 0;

    for (long long l = left; l <= right; ) {
        long long quotient = n / l;
        long long r = min(right, n / quotient);
        long long otherParts = k - r + 2;

        __int128 area = (__int128)quotient * (m / otherParts);
        answer = max(answer, area);

        l = r + 1;
    }

    printInt128(answer);
    cout << '\n';
    return 0;
