#include <iostream>
#include <algorithm>
using namespace std;

using int64 = long long;
using int128 = __int128_t;

void printInt128(int128 x) {
    if (x == 0) {
        cout << 0;
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m, k;
    cin >> n >> m >> k;

    if ((int128)k > (int128)n + m - 2) {
        cout << -1 << '\n';
        return 0;
    }

    if (n > m) swap(n, m);

    int128 sum = (int128)k + 2;
    int128 low128 = max<int128>(1, sum - m);
    int128 high128 = min<int128>(n, sum - 1);

    if (low128 > high128) {
        cout << -1 << '\n';
        return 0;
    }

    int64 low = (int64)low128;
    int64 high = (int64)high128;
    int128 answer = 0;

    auto evaluate = [&](int64 p) {
        if (p < low || p > high) return;
        int128 q = sum - p;
        if (q < 1 || q > m) return;
        int128 value = (int128)(n / p) * (m / (int64)q);
        answer = max(answer, value);
    };

    evaluate(low);
    evaluate(high);

    for (int64 d = 1; d <= n / d; ++d) {
        evaluate(d);
        evaluate(n / d);
    }

    printInt128(answer);
    cout << '\n';
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

using int64 = long long;
using int128 = __int128_t;

void printInt128(int128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m, k;
    cin >> n >> m >> k;

    if (k < 0 || int128(k) > int128(n) + m - 2) {
        cout << -1 << '\n';
        return 0;
    }

    if (n > m) swap(n, m);

    int64 left = max<int64>(0, k - m + 1);
    int64 right = min<int64>(k, n - 1);
    int128 answer = 0;

    for (int64 i = left; i <= right; ) {
        int64 quotient = n / (i + 1);
        int64 end = min(right, n / quotient - 1);

        int128 current = int128(n / (end + 1)) *
                         (m / (k - end + 1));
        answer = max(answer, current);

        i = end + 1;
    }

    printInt128(answer);
    cout << '\n';

    return 0;
}

