using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m, k;
    cin >> n >> m >> k;

    if (k > n + m - 2) {
        cout << -1 << '\n';
        return 0;
    }

    const long long sum = k + 2;
    const long long left = max(1LL, sum - m);
    const long long right = min(n, sum - 1);

    long long answer = 0;

    for (long long a = left; a <= right; ) {
        long long quotient = n / a;
        long long endpoint = min(right, n / quotient);
        long long b = sum - endpoint;

        answer = max(answer, quotient * (m / b));
        a = endpoint + 1;
    }

    cout << answer << '\n';
    return 0;
}

